import { chromium } from 'playwright'; import fs from 'fs'; import path from 'path';
const BASE='https://www.statesideqm.com',THEME='158900125851',OUT='sep18-page-size-verify';fs.mkdirSync(path.join(OUT,'screenshots'),{recursive:true});
const routes=[['Accessories','/collections/accessories-gifts-collectibles'],['Apparel','/collections/apparel'],['Ohio State Guard','/collections/state-guard-series-ohio']];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();p.setDefaultNavigationTimeout(70000);
await p.goto(BASE+'/?preview_theme_id='+THEME,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:15000}).catch(()=>{});await sleep(1400);const established=await p.evaluate(()=>({id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')}));if(established.id!==THEME)throw new Error('wrong theme '+JSON.stringify(established));
const rows=[];for(let i=0;i<routes.length;i++){const [label,route]=routes[i],req=[];const f=r=>{if(r.resourceType()==='fetch'||r.resourceType()==='xhr')req.push(r.url())};p.on('request',f);const response=await p.goto(BASE+route,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await sleep(1200);p.off('request',f);const row=await p.evaluate(({label,route,req,themeId})=>{const n=performance.getEntriesByType('navigation')[0],rs=performance.getEntriesByType('resource'),fcp=performance.getEntriesByName('first-contentful-paint')[0];return{label,route,theme:{id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')},ttfbMs:Math.round(n?.responseStart||0),dclMs:Math.round(n?.domContentLoadedEventEnd||0),loadMs:Math.round(n?.loadEventEnd||0),fcpMs:Math.round(fcp?.startTime||0),resources:rs.length,transferBytes:rs.reduce((s,r)=>s+(r.transferSize||0),0),domNodes:document.getElementsByTagName('*').length,styles:document.querySelectorAll('style').length,scripts:document.scripts.length,images:document.images.length,cards:document.querySelectorAll('[data-testid="product-grid"] .product-grid__item').length,lastPage:document.querySelector('[data-testid="product-grid"]')?.dataset.lastPage||'',page2Section:req.filter(u=>u.includes('section_id=')&&/[?&]page=2(?:&|$)/.test(u)),h1:(document.querySelector('h1')?.textContent||'').replace(/\s+/g,' ').trim(),previewOk:String(window.Shopify?.theme?.id||'')===themeId}}, {label,route,req,themeId:THEME});row.httpStatus=response?.status()??null;rows.push(row);console.log('PAGESIZE',JSON.stringify(row));await p.screenshot({path:path.join(OUT,'screenshots',String(i+1).padStart(2,'0')+'-'+label.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.png'),fullPage:false});await sleep(5000)}
fs.writeFileSync(path.join(OUT,'results.json'),JSON.stringify({generatedAt:new Date().toISOString(),established,rows},null,2));console.log('SUMMARY',JSON.stringify(rows.map(x=>({label:x.label,http:x.httpStatus,preview:x.previewOk,ttfb:x.ttfbMs,dcl:x.dclMs,load:x.loadMs,fcp:x.fcpMs,kb:Math.round(x.transferBytes/1024),resources:x.resources,dom:x.domNodes,styles:x.styles,scripts:x.scripts,images:x.images,cards:x.cards,lastPage:x.lastPage,page2:x.page2Section.length}))));
await c.close();await b.close();